// Managed file - regenerated by `aic workspace update`.
//
// ESLint rule for static `openidm.query("managed/<object>", {
// _queryFilter: "..." })` calls. It validates field names against the
// tenant-specific managed schema snapshot generated beside the `.d.ts` files.

import { readFileSync } from "node:fs";

const QUERY_OPERATOR_NAMES = ["eq", "co", "sw", "lt", "le", "gt", "ge", "pr"];
const QUERY_OPERATOR_LIST = QUERY_OPERATOR_NAMES.join(", ");
const QUERY_OPERATORS = new Set(QUERY_OPERATOR_NAMES);
const QUERY_KEYWORDS = new Set(["and", "or", "not", "true", "false", "null"]);

export function loadManagedQueryFields(url) {
  try {
    return JSON.parse(readFileSync(url, "utf8"));
  } catch (error) {
    if (error && (error.code === "ENOENT" || error.code === "ENOTDIR")) {
      return {};
    }
    throw error;
  }
}

function propertyName(node) {
  if (!node) return null;
  if (node.type === "Identifier") return node.name;
  if (node.type === "Literal" && typeof node.value === "string")
    return node.value;
  return null;
}

function staticString(node) {
  if (!node) return null;
  if (node.type === "Literal" && typeof node.value === "string")
    return node.value;
  if (node.type === "TemplateLiteral" && node.expressions.length === 0) {
    return node.quasis.map((quasi) => quasi.value.cooked).join("");
  }
  return null;
}

function staticStringRange(sourceCode, node) {
  const value = staticString(node);
  if (value === null || !node.range) return null;
  if (node.type === "Literal") {
    const raw = sourceCode.getText(node).slice(1, -1);
    return {
      value,
      start: node.range[0] + 1,
      end: node.range[1] - 1,
      indexMap: cookedToRawIndexMap(raw),
    };
  }
  if (node.type === "TemplateLiteral" && node.expressions.length === 0) {
    const quasi = node.quasis[0];
    return {
      value,
      start: quasi.range[0] + 1,
      end: quasi.range[1] - 1,
      indexMap: cookedToRawIndexMap(quasi.value.raw),
    };
  }
  return null;
}

// Exported for repo-side parser tests; user workspaces consume the rule API.
export function cookedToRawIndexMap(raw) {
  const map = [];
  let cooked = 0;
  let rawIndex = 0;

  map[cooked] = 0;
  while (rawIndex < raw.length) {
    const start = rawIndex;
    let cookedLength = 1;
    if (raw[rawIndex] === "\\" && rawIndex + 1 < raw.length) {
      const escape = escapedRawShape(raw, rawIndex);
      rawIndex += escape.rawLength;
      cookedLength = escape.cookedLength;
    } else {
      rawIndex++;
    }
    if (cookedLength === 0) {
      map[cooked] = rawIndex;
      continue;
    }
    map[cooked] = start;
    for (let i = 1; i < cookedLength; i++) {
      map[cooked + i] = start;
    }
    cooked += cookedLength;
    map[cooked] = rawIndex;
  }

  return map;
}

function escapedRawShape(raw, start) {
  const next = raw[start + 1];
  if (isLineContinuation(raw, start)) {
    return {
      rawLength: next === "\r" && raw[start + 2] === "\n" ? 3 : 2,
      cookedLength: 0,
    };
  }
  if (next === "u" && raw[start + 2] === "{") {
    const close = raw.indexOf("}", start + 3);
    if (close === -1) return { rawLength: 2, cookedLength: 1 };
    const codePoint = Number.parseInt(raw.slice(start + 3, close), 16);
    return {
      rawLength: close - start + 1,
      cookedLength: codePoint > 0xffff ? 2 : 1,
    };
  }
  if (next === "u") {
    return { rawLength: Math.min(6, raw.length - start), cookedLength: 1 };
  }
  if (next === "x") {
    return { rawLength: Math.min(4, raw.length - start), cookedLength: 1 };
  }
  if (/[0-7]/.test(next)) {
    let length = 2;
    while (length < 4 && /[0-7]/.test(raw[start + length])) {
      length++;
    }
    return {
      rawLength: Math.min(length, raw.length - start),
      cookedLength: 1,
    };
  }
  return { rawLength: 2, cookedLength: 1 };
}

function isLineContinuation(raw, start) {
  const next = raw[start + 1];
  return (
    next === "\n" ||
    next === "\u2028" ||
    next === "\u2029" ||
    next === "\r"
  );
}

function isOpenidmQuery(node) {
  if (!node || node.type !== "MemberExpression" || node.computed) return false;
  return (
    node.object &&
    node.object.type === "Identifier" &&
    node.object.name === "openidm" &&
    propertyName(node.property) === "query"
  );
}

function queryFilterProperty(paramsNode) {
  if (!paramsNode || paramsNode.type !== "ObjectExpression") return null;
  for (const property of paramsNode.properties) {
    if (property.type !== "Property") continue;
    if (propertyName(property.key) === "_queryFilter") return property.value;
  }
  return null;
}

function tokenizeQueryFilter(filter) {
  const tokens = [];
  const issues = [];
  let i = 0;

  while (i < filter.length) {
    const ch = filter[i];
    if (/\s/.test(ch)) {
      i++;
      continue;
    }
    if (ch === '"' || ch === "'") {
      const quote = ch;
      const start = i;
      let closed = false;
      i++;
      while (i < filter.length) {
        if (filter[i] === "\\") {
          i += 2;
          continue;
        }
        if (filter[i] === quote) {
          i++;
          closed = true;
          break;
        }
        i++;
      }
      if (!closed) {
        issues.push({
          kind: "syntax",
          start,
          end: i,
          message: "Unterminated quoted value in _queryFilter.",
        });
      }
      tokens.push({ type: "string", start, end: i });
      continue;
    }
    if ("!()[],".includes(ch)) {
      tokens.push({ type: "punct", value: ch, start: i, end: i + 1 });
      i++;
      continue;
    }

    const start = i;
    while (
      i < filter.length &&
      !/\s/.test(filter[i]) &&
      !"\"'!()[],".includes(filter[i])
    ) {
      i++;
    }
    tokens.push({ type: "word", value: filter.slice(start, i), start, end: i });
  }

  return { tokens, issues };
}

function isFieldWord(token) {
  if (!token || token.type !== "word") return false;
  const lower = token.value.toLowerCase();
  if (QUERY_OPERATORS.has(lower) || QUERY_KEYWORDS.has(lower)) return false;
  return !/^-?\d+(?:\.\d+)?$/.test(token.value);
}

function suggestionFor(root, knownFields) {
  const candidates = knownFields.filter((candidate) => candidate !== root);
  let best = null;

  for (const candidate of candidates) {
    const distance = levenshtein(root, candidate);
    if (distance <= 2 && (!best || distance < best.distance)) {
      best = { candidate, distance };
    }
  }

  return best ? best.candidate : null;
}

function queryFieldRoot(field) {
  // AIC's web console may serialize CREST query fields with a leading slash
  // (`/_id eq "..."`). The server accepts both `_id` and `/_id`; treat the
  // slash form as a JSON-pointer-like spelling of the same field path.
  return field.replace(/^\/+/, "").split("/")[0];
}

function queryFieldRootEnd(field) {
  const leading = field.match(/^\/*/)[0].length;
  const remainder = field.slice(leading);
  const slash = remainder.indexOf("/");
  return leading + (slash === -1 ? remainder.length : slash);
}

function levenshtein(left, right) {
  const previous = Array.from({ length: right.length + 1 }, (_, i) => i);
  const current = Array.from({ length: right.length + 1 }, () => 0);

  for (let i = 1; i <= left.length; i++) {
    current[0] = i;
    for (let j = 1; j <= right.length; j++) {
      const cost = left[i - 1] === right[j - 1] ? 0 : 1;
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + cost
      );
    }
    for (let j = 0; j < previous.length; j++) {
      previous[j] = current[j];
    }
  }

  return previous[right.length];
}

export function validateQueryFilterFields(filter, knownFields) {
  const known = new Set(knownFields);
  const parser = new QueryFilterParser(filter, known, knownFields);
  const issues = parser.parse();

  return issues;
}

class QueryFilterParser {
  constructor(filter, known, knownFields) {
    const { tokens, issues } = tokenizeQueryFilter(filter);
    this.tokens = tokens;
    this.issues = issues;
    this.known = known;
    this.knownFields = knownFields;
    this.pos = 0;
    this.filterLength = filter.length;
  }

  parse() {
    if (this.tokens.length === 0) return this.issues;

    this.parseExpression();
    while (!this.atEnd()) {
      const token = this.peek();
      if (this.isPunct(token, ")")) {
        this.syntax(token, "Unexpected ')' in _queryFilter.");
        this.advance();
        continue;
      }
      this.syntax(token, "Unexpected _queryFilter token '{{token}}'.", {
        token: tokenText(token),
      });
      this.advance();
    }

    return this.issues;
  }

  parseExpression() {
    this.parseOr();
  }

  parseOr() {
    this.parseAnd();
    while (this.matchKeyword("or")) {
      if (this.atEnd() || this.isPunct(this.peek(), ")")) {
        this.syntaxPrevious("Expected _queryFilter expression after 'OR'.");
        return;
      }
      this.parseAnd();
    }
  }

  parseAnd() {
    this.parseNot();
    while (this.matchKeyword("and")) {
      if (this.atEnd() || this.isPunct(this.peek(), ")")) {
        this.syntaxPrevious("Expected _queryFilter expression after 'AND'.");
        return;
      }
      this.parseNot();
    }
  }

  parseNot() {
    if (this.matchKeyword("not")) {
      const operator = this.previous();
      this.syntax(
        operator,
        "Unsupported _queryFilter negation '{{operator}}'. Use '!'.",
        { operator: operator.value }
      );
      if (!this.atEnd() && !this.isPunct(this.peek(), ")")) {
        this.parseNot();
      }
      return;
    }

    if (this.matchPunct("!")) {
      const operator = this.previous();
      if (this.atEnd() || this.isPunct(this.peek(), ")")) {
        this.syntax(
          operator,
          "Expected _queryFilter expression after '{{operator}}'.",
          { operator: tokenText(operator) }
        );
        return;
      }
      this.parseNot();
      return;
    }
    this.parsePrimary();
  }

  parsePrimary() {
    if (this.matchKeyword("true") || this.matchKeyword("false")) return;

    if (this.matchPunct("(")) {
      const open = this.previous();
      if (this.matchPunct(")")) {
        this.syntax(open, "Empty _queryFilter group.");
        return;
      }

      this.parseExpression();
      if (!this.matchPunct(")")) {
        const token = this.peek() || open;
        this.syntax(token, "Expected ')' to close _queryFilter group.");
      }
      return;
    }

    if (this.isPunct(this.peek(), ")")) return;
    this.parseComparison();
  }

  parseComparison() {
    const field = this.peek();
    if (!isFieldWord(field)) {
      if (field) {
        this.syntax(field, "Expected _queryFilter field before '{{token}}'.", {
          token: tokenText(field),
        });
        this.advance();
      }
      return;
    }

    this.advance();
    this.validateField(field);

    const operator = this.peek();
    if (!operator) {
      this.syntax(field, "Expected _queryFilter operator after '{{field}}'.", {
        field: field.value,
      });
      return;
    }

    if (operator.type !== "word") {
      this.syntax(
        operator,
        "Expected _queryFilter operator before '{{token}}'.",
        { token: tokenText(operator) }
      );
      return;
    }

    const operatorName = operator.value.toLowerCase();
    if (!QUERY_OPERATORS.has(operatorName)) {
      if (QUERY_KEYWORDS.has(operatorName)) {
        this.syntax(
          operator,
          "Expected _queryFilter operator before '{{token}}'.",
          { token: tokenText(operator) }
        );
      } else {
        this.issues.push({
          kind: "operator",
          operator: operator.value,
          start: operator.start,
          end: operator.end,
        });
        this.advance();
        this.recoverValue();
      }
      return;
    }

    this.advance();
    if (operatorName !== "pr") {
      this.parseValue(operator);
    }
  }

  parseValue(operator) {
    const value = this.peek();
    if (
      !value ||
      this.isPunct(value, ")") ||
      this.isKeyword(value, "and") ||
      this.isKeyword(value, "or")
    ) {
      this.syntax(
        operator,
        "Expected _queryFilter value after '{{operator}}'.",
        { operator: operator.value }
      );
      return;
    }

    if (this.isPunct(value, "[")) {
      this.syntax(
        value,
        "Array values are not valid in AIC managed _queryFilter expressions."
      );
      this.consumeArray();
      return;
    }

    if (value.type === "string" || value.type === "word") {
      this.advance();
      return;
    }

    this.syntax(value, "Expected _queryFilter value before '{{token}}'.", {
      token: tokenText(value),
    });
    this.advance();
  }

  recoverValue() {
    const value = this.peek();
    if (!value || this.isPunct(value, ")")) return;
    if (this.isPunct(value, "[")) {
      this.consumeArray();
      return;
    }
    this.advance();
  }

  consumeArray() {
    const open = this.peek();
    if (!this.matchPunct("[")) return;
    let depth = 1;
    while (!this.atEnd()) {
      if (this.matchPunct("[")) {
        depth++;
        continue;
      }
      if (this.matchPunct("]")) {
        depth--;
        if (depth === 0) return;
        continue;
      }
      if (depth === 1 && this.isPunct(this.peek(), ")")) {
        return;
      }
      this.advance();
    }

    this.syntax(open, "Expected ']' to close _queryFilter array.");
  }

  validateField(field) {
    const root = queryFieldRoot(field.value);
    if (this.known.has(root)) return;

    const rootEnd = queryFieldRootEnd(field.value);
    this.issues.push({
      kind: "field",
      field: field.value,
      root,
      start: field.start,
      end: field.start + rootEnd,
      suggestion: suggestionFor(root, this.knownFields),
    });
  }

  peek() {
    return this.tokens[this.pos] || null;
  }

  previous() {
    return this.tokens[this.pos - 1] || null;
  }

  advance() {
    if (!this.atEnd()) this.pos++;
    return this.previous();
  }

  atEnd() {
    return this.pos >= this.tokens.length;
  }

  matchPunct(value) {
    if (!this.isPunct(this.peek(), value)) return false;
    this.advance();
    return true;
  }

  matchKeyword(value) {
    if (!this.isKeyword(this.peek(), value)) return false;
    this.advance();
    return true;
  }

  isPunct(token, value) {
    return Boolean(token && token.type === "punct" && token.value === value);
  }

  isKeyword(token, value) {
    return Boolean(
      token && token.type === "word" && token.value.toLowerCase() === value
    );
  }

  syntax(token, message, data = {}) {
    const start = token ? token.start : this.filterLength;
    const end = token ? token.end : this.filterLength;
    this.issues.push({
      kind: "syntax",
      start,
      end: Math.max(end, start + 1),
      message,
      data,
    });
  }

  syntaxPrevious(message, data = {}) {
    this.syntax(this.previous(), message, data);
  }
}

function tokenText(token) {
  if (!token) return "end of query";
  if (token.type === "punct") return token.value;
  if (token.type === "string") return "quoted value";
  return token.value;
}

function locFromIndex(sourceCode, stringRange, relativeIndex) {
  return sourceCode.getLocFromIndex(
    stringRange.start + rawOffsetForIndex(stringRange, relativeIndex)
  );
}

function rangeFromIssue(stringRange, issue) {
  return [
    stringRange.start + rawOffsetForIndex(stringRange, issue.start),
    stringRange.start + rawOffsetForIndex(stringRange, issue.end),
  ];
}

// Exported with cookedToRawIndexMap for repo-side source-mapping tests.
export function rawOffsetForIndex(stringRange, relativeIndex) {
  const map = stringRange.indexMap;
  if (!map) return relativeIndex;
  if (relativeIndex < 0) return 0;
  if (relativeIndex === 0) return map[0] || 0;
  if (relativeIndex >= map.length) return stringRange.end - stringRange.start;
  return map[relativeIndex];
}

function replacementForField(field, suggestion) {
  const leadingSlash = field.startsWith("/") ? "/" : "";
  return `${leadingSlash}${suggestion}`;
}

export function openidmQueryFilterRule(managedFields) {
  return {
    meta: {
      type: "problem",
      docs: {
        description:
          "validate literal openidm.query _queryFilter fields against generated managed-object schema fields",
      },
      hasSuggestions: true,
      schema: [],
    },
    create(context) {
      const sourceCode = context.sourceCode || context.getSourceCode();
      return {
        CallExpression(node) {
          if (!isOpenidmQuery(node.callee)) return;

          const resource = staticString(node.arguments[0]);
          if (
            !resource ||
            !Object.prototype.hasOwnProperty.call(managedFields, resource)
          ) {
            return;
          }

          const queryFilterNode = queryFilterProperty(node.arguments[1]);
          const queryFilter = staticStringRange(sourceCode, queryFilterNode);
          if (!queryFilter) return;

          const knownFields = managedFields[resource];
          const issues = validateQueryFilterFields(
            queryFilter.value,
            knownFields
          );
          for (const issue of issues) {
            const range = rangeFromIssue(queryFilter, issue);
            const loc = {
              start: locFromIndex(sourceCode, queryFilter, issue.start),
              end: locFromIndex(sourceCode, queryFilter, issue.end),
            };
            if (issue.kind === "operator") {
              context.report({
                node: queryFilterNode,
                loc,
                message:
                  "Unknown _queryFilter operator '{{operator}}'. Expected one of: {{operators}}.",
                data: {
                  operator: issue.operator,
                  operators: QUERY_OPERATOR_LIST,
                },
              });
              continue;
            }
            if (issue.kind === "syntax") {
              context.report({
                node: queryFilterNode,
                loc,
                message: issue.message,
                data: issue.data || {},
              });
              continue;
            }

            context.report({
              node: queryFilterNode,
              loc,
              message: issue.suggestion
                ? "Unknown _queryFilter field '{{field}}' for {{resource}}. Did you mean '{{suggestion}}'?"
                : "Unknown _queryFilter field '{{field}}' for {{resource}}.",
              data: {
                field: issue.field,
                resource,
                suggestion: issue.suggestion,
              },
              suggest: issue.suggestion
                ? [
                    {
                      desc: `Replace with '${replacementForField(
                        issue.field,
                        issue.suggestion
                      )}'`,
                      fix(fixer) {
                        return fixer.replaceTextRange(
                          range,
                          replacementForField(issue.field, issue.suggestion)
                        );
                      },
                    },
                  ]
                : [],
            });
          }
        },
      };
    },
  };
}
